/// <summary>
/// Checks if HK2 Group can be deleted.
/// </summary>
/// <returns>true or false</returns>
public boolean validateDelete()
{
    InventTable lInventTable;
    boolean ret;

    ret = super();

    if(this.HK2GroupId != '')
    {
        select firstonly lInventTable
            where lInventTable.NDXHK2GroupRefRecId == this.RecId;

        if(lInventTable)
        {
            return checkFailed(strFmt("@NDX:NDXHK2InUse", lInventTable.ItemId));
        }
    }

    return ret;
}

/// <summary>
/// Finds HK2 factor group record
/// </summary>
/// <param name = "_groupId">Group id</param>
/// <param name = "_update">for update</param>
/// <returns>KCS_HK2FactorGroup record</returns>
static KCS_HK2FactorGroup find(KCS_HK2GroupId _groupId, boolean _update = false)
{
    KCS_HK2FactorGroup factorGroup;
    ;
    if (_groupId)
    {
        factorGroup.selectForUpdate(_update);

        select firstonly factorGroup
            where factorGroup.HK2GroupId == _groupId;
    }
    return factorGroup;
}

/// <summary>
/// Finds HK2 factor group record by date
/// </summary>
/// <param name = "_groupId">Group id</param>
/// <param name = "_fromDate">from date</param>
/// <param name = "_update">for update</param>
/// <returns>KCS_HK2FactorGroup record</returns>
static KCS_HK2FactorGroup findDate(KCS_HK2GroupId _groupId, FromDate _fromDate, boolean _update = false)
{
    KCS_HK2FactorGroup factorGroup;

    if(_groupId)
    {
        factorGroup.selectForUpdate(_update);

        select firstonly factorGroup
            where factorGroup.HK2GroupId == _groupId
            && factorGroup.FromDate   <= _fromDate;
    }
    return factorGroup;
}

/// <summary>
/// Finds HK2 factor group record by date
/// </summary>
/// <param name = "_hk2GroupRecId">Group id</param>
/// <param name = "_fromDate">from date</param>
/// <param name = "_update">for update</param>
/// <returns>KCS_HK2FactorGroup record</returns>
static KCS_HK2FactorGroup findDateRecId(RecId _hk2GroupRecId, FromDate _fromDate, boolean _update = false)
{
    KCS_HK2FactorGroup factorGroup;

    if(_hk2GroupRecId)
    {
        factorGroup.selectForUpdate(_update);

        select firstonly factorGroup
            where factorGroup.RecId == _hk2GroupRecId
            && factorGroup.FromDate   <= _fromDate;
    }
    return factorGroup;
}

/// <summary>
/// Find record by RecId
/// </summary>
/// <param name = "_recId">RecId of a record</param>
/// <param name = "_update">for update</param>
/// <returns>KCS_HK2FactorGroup record</returns>
static KCS_HK2FactorGroup findByRecId(RecId _recId, boolean _update = false)
{
    KCS_HK2FactorGroup factorGroup;

    if (_recId)
    {
        factorGroup.selectForUpdate(_update);

        select firstonly factorGroup
            where factorGroup.RecId == _recId;
    }
    return factorGroup;
}

public void update()
{
    KCS_HK2FactorGroup lKCS_HK2FactorGroupOrig = this.orig();
    super();

    if(lKCS_HK2FactorGroupOrig.HK2Factor != this.HK2Factor || lKCS_HK2FactorGroupOrig.FromDate == this.FromDate)
    {
        NDXHK2GroupHistory::createByKCS_HK2FactorGroup(this);
    }

}
